$ErrorActionPreference='SilentlyContinue';$TaskName='ZorinTrustHostAgent';$StateDir=Join-Path $env:APPDATA 'ZorinTrust';Import-Module ScheduledTasks -ErrorAction SilentlyContinue;Stop-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue;Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false -ErrorAction SilentlyContinue;$pids=@();try{$pids=@(Get-NetTCPConnection -LocalAddress '127.0.0.1' -LocalPort 47472 -State Listen -ErrorAction Stop|Select-Object -ExpandProperty OwningProcess -Unique)}catch{};$pids|ForEach-Object{Stop-Process -Id $_ -Force -ErrorAction SilentlyContinue};Start-Sleep -Milliseconds 200;Remove-Item (Join-Path $StateDir 'session.json') -Force -ErrorAction SilentlyContinue;Remove-Item (Join-Path $StateDir 'owner-mode.json') -Force -ErrorAction SilentlyContinue;Write-Host 'Zorin Trust autostart removed. Pairing, policy, control token and identity were intentionally kept.'
